import copy
import hashlib
import json
import os
import sys
import time
from types import SimpleNamespace

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402

R = "data/p1v4/runs"
FEATS = "data/p1v4/feats"
PARTS = ("r_hear", "s_move")
VARIANTS = {"dclean": 0, "dnoise5": 5, "dnoise10": 10}
SPLITS = ("dev", "test", "replication")
API_NAME = {"b2fast": "B2-fast", "b2strong": "B2-strong", "b3": "B3"}
FIVE = ("conv", "event", "second", "noise", "voice")             # = p1v4_test_report.FIVE (amendment 13.1)


def patch_folders():
    """Let p1v4_data (Context, the front-end scripts, the API script) read <split>_<variant> folders like a split;
    test and replication variants stay sealed until the final run."""
    orig = D.folders

    def folders(which, final=False):
        if isinstance(which, str) and "_d" in which and which.split("_d")[0] in SPLITS:
            if which.split("_d")[0] != "dev":
                D.check_folder_name(which)          # sealed until the final run; the freeze record checked once
            return [f"{D.RENDER}/{which}"]
        return orig(which, final)
    D.folders = folders


def frozen(split):
    import p1v4_freeze as FZ
    st = json.load(open(FZ.REHEARSAL))["settings"] if split == "dev" else FZ.verify_or_stop()["settings"]
    if sorted(st["noise_db"]) != sorted(v for v in VARIANTS.values() if v):
        raise SystemExit(f"noise levels {st['noise_db']} in the record differ from {VARIANTS}")
    return st


def out_dir(split, variant, *sub):
    d = os.path.join(R, "final", split, "noise", variant, *sub)
    os.makedirs(d, exist_ok=True)
    return d


def base_rows(split):
    """The main body of the split's R-hear and S-move parts (amendment 12: "main body"); subset units are left out."""
    return [r for r in D.load_rows(split) if r["part"] in PARTS and r.get("subset") is None]


def api_mode(system, split, st):
    """(mode, effective entry) of an API rival: the mode the test-day probe fixed (dev without a modes file:
    probabilities) and p1v4_api.effective's setting for it (amendment 13.2)."""
    import p1v4_api as API
    p = f"{R}/final/{split}/api/modes.json"
    if os.path.exists(p):
        mode = json.load(open(p))[API.NAME[system]]
    elif split == "dev":
        mode = "probabilities"
    else:
        raise SystemExit(f"{p} missing: run the probe first (amendment 2.2)")
    return mode, API.effective(system, split, mode, st)


# ------------------------------------------------------------------------------------------------ render

def render(split, variant):
    import soundfile as sf
    import p1v4_units as U
    frozen(split)
    patch_folders()
    db = VARIANTS[variant]
    folder = f"{split}_{variant}"
    out = os.path.join(D.RENDER, folder)
    os.makedirs(out, exist_ok=True)
    rows = base_rows(split)
    meta, info = [], {"split": split, "variant": variant, "db_louder_noise": db, "units_scaled": 0}
    if db == 0:
        meta = rows
    else:
        A = U.Assets(split)
        by = {}
        for r in rows:
            by.setdefault(r["unit"], []).append(r)
        for u, rs in sorted(by.items()):
            spec = copy.deepcopy(rs[0]["spec"])
            spec["snr_db"] = round(spec["snr_db"] - db, 2)
            tls = {r["version"]: SimpleNamespace(src=r["sources"], points=r["points"], assistant=r["assistant"])
                   for r in rs}
            audio, gain_db = U.render_versions(spec, tls, A)
            info["units_scaled"] += int(abs(gain_db - rs[0]["gain_db"]) > 1e-9)
            for r in rs:
                nr = copy.deepcopy(r)
                nr["spec"]["snr_db"], nr["gain_db"] = spec["snr_db"], gain_db
                nr["peak"] = round(float(np.abs(audio[r["version"]]).max()) / 32767, 4)
                for p in nr["points"]:
                    w = U.windows(audio[r["version"]], [p])[0]
                    assert len(w) == int(D.WIN_S * D.SR)
                    path = os.path.join(out, f"{u}_{r['version']}_p{p['k']}.wav").replace("\\", "/")
                    sf.write(path, w, U.SR, subtype="PCM_16")
                    p["window"], p["sha256"] = path, hashlib.sha256(open(path, "rb").read()).hexdigest()
                meta.append(nr)
    with open(os.path.join(out, "meta.jsonl"), "w", encoding="utf-8") as f:
        for r in meta:
            f.write(json.dumps(r, ensure_ascii=False) + "\n")
    info.update(rows=len(meta), units=len({r["unit"] for r in meta}))
    json.dump(info, open(os.path.join(out_dir(split, variant), "render_info.json"), "w"), indent=1)
    print(json.dumps(info))


# ------------------------------------------------------------------------------------------------ front end

def front(split, variant):
    import p1v4_asr_turbo as AT
    import p1v4_feats as FE
    import p1v4_l2 as L2
    import p1v4_sed as SED
    import p1v4_voxturn as VT
    frozen(split)
    patch_folders()
    folder = f"{split}_{variant}"
    ckpt = f"{R}/sed/sed.pt"
    FE.run(folder, ckpt)
    AT.main(folder)
    SED.windows(ckpt, folder, f"{FEATS}/sed_win_{folder}")
    VT.main(folder, f"{FEATS}/voxturn_{folder}.json")
    L2.features(folder)
    print(f"front end done: {folder}", flush=True)


# ------------------------------------------------------------------------------------------------ local systems

def save(sc, path):
    json.dump({"|".join(map(str, k)): v for k, v in sc.items()}, open(path, "w"))


def local(split, variant):
    import soundfile as sf
    import torch
    import torch.nn as nn
    import p1v4_b1 as B1
    import p1v4_l1 as L1
    import p1v4_l2 as L2
    import p1v4_l3 as L3
    import p1v4_readout as RO
    import p1v4_readout_2c as R2C
    import p1v4_readout_2d as R2D
    import p1v4_readout_allclass as AC
    st = frozen(split)
    patch_folders()
    D.gpu_guard()
    folder = f"{split}_{variant}"
    od = out_dir(split, variant)
    rows = D.load_rows(folder)
    ctx = C.Context(folder)
    wins = D.windows_of(rows, folder)
    rows_by = {(r["unit"], r["version"]): r for r in rows}
    model = L1.build()
    L1.load_new_state(model, torch.load(f"{R}/l1/l1_new.pt", weights_only=True))
    model.eval()
    items = []
    for w in wins:
        r = rows_by[w["key"]]
        text, asks = ctx.situation(r, w["k"], "full")
        items.append({"id": w["id"], "path": w["path"], "text": text,
                      "marker": "agent" if w["assistant_speaking"] else "user",
                      "qs": [q for q in ("S", "R") if any(a.startswith(q + ":") for a in asks)]})
    H, E, SM, SX, QW, QT, PO = [], [], [], [], [], [], []
    for i in range(0, len(items), 8):
        chunk = items[i:i + 8]
        waves = torch.stack([torch.from_numpy(sf.read(it["path"], dtype="float32")[0]) for it in chunk]).cuda()
        h, e, qs, po = RO.forward_states(model, waves, [it["text"] for it in chunk], [it["marker"] for it in chunk],
                                         [[RO.TASK[q] for q in it["qs"]] for it in chunk])
        sm, sx, _ = R2D.per_second(model.vt, waves)
        H.append(h.astype(np.float16))
        E.append(e.astype(np.float16))
        SM.append(sm.astype(np.float16))
        SX.append(sx.astype(np.float16))
        QW.append(qs + i)
        QT += [q for it in chunk for q in it["qs"]]
        PO.append(po)
    z = {"states": np.concatenate(H), "ears": np.concatenate(E), "q_win": np.concatenate(QW), "q_task": np.array(QT),
         "p_old": np.concatenate(PO), "ids": np.array([it["id"] for it in items]),
         "sec_mean": np.concatenate(SM), "sec_max": np.concatenate(SX)}
    np.savez(f"{od}/feats.npz", **z)
    del model
    torch.cuda.empty_cache()
    save(RO.scores_of(z, None, None), f"{od}/L1.json")
    save(RO.scores_of(z, "ears", AC.load_allclass()), f"{od}/2b_ears.json")
    save(RO.scores_of(z, "ears", R2C.load_2c()), f"{od}/2c_ears.json")
    save(R2D.scores_2d(z, R2D.Sec(None, z["ids"], z["sec_mean"], z["sec_max"]), R2D.load_2d()), f"{od}/2d.json")
    lists = json.load(open(f"{R}/b1/mined_phrases.json"))
    one = B1.Grid(np.array([[B1.GRID[n].index(st["b1"]["setting"][n]) for n in B1.GRID]], np.int16))
    assert one.setting(0) == st["b1"]["setting"]
    dec = B1.decisions_for(B1.point_inputs(rows, ctx, lists), one, 0)
    json.dump({"|".join(map(str, k)): v for k, v in dec.items()}, open(f"{od}/B1-strong.json", "w"))
    for name, sub in (("L2", "l2"), ("T", "t"), ("T0", "t0"), ("T0-single", "t0single")):
        ck = torch.load(f"{R}/{sub}/{sub}.pt", weights_only=False)
        ids, X = L2.load_X(folder, sub)
        X = ((X - ck["mu"]) / ck["sd"]).astype(np.float32)
        d = X.shape[1]
        net = nn.Linear(d, 2) if ck["kind"] == "lr" else nn.Sequential(nn.Linear(d, 256), nn.GELU(), nn.Dropout(0.2),
                                                                       nn.Linear(256, 2))
        net.load_state_dict(ck["state"])
        save(L2.scores_of(net.cuda().eval(), X, ids), f"{od}/{name}.json")
    ck = torch.load(f"{R}/l3/l3.pt", weights_only=False)
    w3, _, y, X, _, _ = L3.data(folder, ck["mu"], ck["sd"])
    net = L3.Net(X.shape[1]).cuda()
    net.load_state_dict(ck["state"])
    save(L3.score(net, w3, X, y), f"{od}/L3.json")
    print(f"local systems done: {folder}", flush=True)


# ------------------------------------------------------------------------------------------------ API rivals

def api(system, key_path, split, variant, limit=None, max_usd=400.0, max_rounds=8):
    """The rival at p1v4_api.effective's setting in the probed mode (amendment 13.2: a passed drift check of the same
    day, or a re-choice made today, is required off dev); re-asked in whole rounds until no question is missing
    (amendment 13.1); the score file is named by the mode, with its .meta.json sidecar."""
    import p1v4_api as API
    st = frozen(split)
    patch_folders()
    folder = f"{split}_{variant}"
    mode, e = api_mode(system, split, st)
    answers, setting = mode == "answers", e["setting"]
    if split != "dev":                       # post-fix review M5: the same rule as every other runner
        ok, why = API.ok_today(system, split, st)
        if not ok:
            raise SystemExit(f"{API.NAME[system]}: {why} (amendment 13.2)")
    od = out_dir(split, variant, "api")

    def run_dir(system_, setting_, *a, **kw):
        return os.path.join(od, system_, setting_ + ("_answers" if answers else ""))
    API.run_dir = run_dir
    if limit:
        if split != "dev":
            raise SystemExit("--limit is for the dev rehearsal only")
        keep = sorted({r["unit"] for r in D.load_rows(folder)})[:limit]
        orig = API.dev_points

        def dev_points(sample=None, split_=folder, seed=0):
            rows_, pts = orig(None, split_, seed)
            return rows_, [(r, k) for r, k in pts if r["unit"] in keep]
        API.dev_points = dev_points
    spent = 0.0
    for rnd in range(1, max_rounds + 1):
        rr = API.run(system, setting, key_path, split=folder, max_usd=max_usd - spent, workers=16, answers=answers)
        spent += rr["usd"]
        missing = rr["expected"] - rr["already"] - rr["answered"]
        print(f"{API_NAME[system]} {folder} round {rnd}: {missing} missing, ${spent:.2f}", flush=True)
        if rr["stop_kind"] == "no_logprobs":
            raise SystemExit("logprobs lost mid-run: amendment 2.3 (switch the rival to answers, ask again)")
        if rr["stop_kind"] == "budget" or spent >= max_usd:
            raise SystemExit(f"budget ${max_usd:.0f} reached with {missing} missing")
        if missing <= 0:
            break
        time.sleep(min(600, 60 * rnd))
    API.split_scores(system, setting, folder, answers)          # off dev: no score file while a question is missing
    sfx = "_answers" if answers else ""
    src = os.path.join(od, system, f"scores_{folder}_{setting}{sfx}.json")
    dst = os.path.join(out_dir(split, variant), f"{API_NAME[system]}_{mode}.json")
    os.replace(src, dst)
    os.replace(API.meta_path(src), API.meta_path(dst))


# ------------------------------------------------------------------------------------------------ report

def keyed(d):
    return {(k.split("|")[0], k.split("|")[1], int(k.split("|")[2])): v for k, v in d.items()}


def detector(rows, ctx):
    hit, n_real, fa, n_none = ({c: 0 for c in D.DET_CLASSES} for _ in range(4))
    for r in rows:
        for p in r["points"]:
            t = p["t"]
            real = {c for c, _, _ in D.window_events(r, t)}
            det = {s[0] for s in ctx.point(r, p["k"])[3] if s[3] >= 0.5 and s[2] > t - D.WIN_S and s[1] < t}
            for c in D.DET_CLASSES:
                if c in real:
                    n_real[c] += 1
                    hit[c] += c in det
                else:
                    n_none[c] += 1
                    fa[c] += c in det
    return {c: {"recall": hit[c] / max(1, n_real[c]), "n_real": n_real[c], "false_alarm": fa[c] / max(1, n_none[c]),
                "n_none": n_none[c]} for c in D.DET_CLASSES}


def boot_se_factors(units, lab, stat, B=2000, seed=1):
    """As p1v4_grounding_report.boot_se with any cluster factors (lab: {factor: label per unit}); also the t critical
    value of package v0.6 15.2 (degrees of freedom = clusters of the factor with the largest one-way SE, minus 1)."""
    import itertools
    from scipy.stats import t as tdist
    rng = np.random.default_rng(seed)
    names = list(lab)

    def var_by(keys):
        labels = ["|".join(str(lab[k][i]) for k in keys) for i in range(len(units))]
        lv = {x: j for j, x in enumerate(sorted(set(labels)))}
        idx = np.array([lv[x] for x in labels])
        w = rng.poisson(1.0, (B, len(lv)))[:, idx].astype(float)
        return float(np.var(stat(w)))
    one = {k: var_by([k]) for k in names}
    total = 0.0
    for r in range(1, len(names) + 1):
        for combo in itertools.combinations(names, r):
            total += (-1) ** (r + 1) * (one[combo[0]] if r == 1 else var_by(list(combo)))
    se = float(np.sqrt(max(total, max(one.values()))))
    dom = max(one, key=one.get)
    g = len(set(lab[dom]))
    return se, {"dominant_factor": dom, "clusters": {k: len(set(lab[k])) for k in names},
                "t_crit": float(tdist.ppf(0.975, max(1, g - 1)))}


def g5_values(T, v, readers):
    """Per main-body unit, the mean over `readers` of the gap change (2d minus reader, level v minus clean), and
    whether the unit is an R-hear one (G5: parts weighted equally)."""
    us_all, is_r, val = [], [], []
    for part in PARTS:
        us = sorted(u for u, x in T["dclean"]["2d"].items() if x["part"] == part and x["subset"] is None)

        def rt2(lv, n, us=us):
            return np.array([T[lv][n][u]["right"] for u in us], float)
        a = np.mean([(rt2(v, "2d") - rt2(v, n)) - (rt2("dclean", "2d") - rt2("dclean", n)) for n in readers], 0)
        us_all += us
        is_r += [part == "r_hear"] * len(us)
        val += list(a)
    return us_all, np.array(is_r), np.array(val)


def g5_stat(GR, cl, us_all, is_r, val, keep=None):
    keep = np.ones(len(us_all), bool) if keep is None else keep
    us = [u for u, k in zip(us_all, keep) if k]
    ir, vv = is_r[keep], val[keep]
    if not ir.any() or ir.all():
        return {"n_units": len(us), "note": "one part only"}
    c = GR.criterion(us, cl, {}, lambda w: 0.5 * GR.wmean(w[:, ir], vv[ir]) + 0.5 * GR.wmean(w[:, ~ir], vv[~ir]),
                     lambda: float(0.5 * vv[ir].mean() + 0.5 * vv[~ir].mean()))
    return {"point": c["point"], "ci95": c["ci95"], "n_units": len(us)}


def report(split):
    import p1v4_api as API
    import p1v4_grounding_report as GR
    import p1v4_score as S
    import p1v4_test_report as TR
    st = frozen(split)
    patch_folders()
    modes = TR.api_modes(split)
    readers_g5 = tuple(st["label_readers_g5"])                   # amendment 12: the label readers of G5
    sg = S.load_groups(split)
    cl = GR.cluster_table(D.load_rows(split), split)
    th = {"2d": (st["main"]["th_s"], st["main"]["th_r"]),
          "2b ears": (st["readouts"]["2b ears"]["th_s"], st["readouts"]["2b ears"]["th_r"]),
          "2c ears": (st["readouts"]["2c ears"]["th_s"], st["readouts"]["2c ears"]["th_r"])}
    for n in ("L1", "L2", "L3", "T", "T0", "T0-single"):
        th[n] = (st["local"][n]["th_s"], st["local"][n]["th_r"])
    eff = {}
    for sd, n in API_NAME.items():
        eff[n] = API.effective(sd, split, modes[n], st)
        th[n] = (eff[n]["th_s"], eff[n]["th_r"])
    files = {"2d": "2d", "2b ears": "2b_ears", "2c ears": "2c_ears", "L1": "L1", "L2": "L2", "L3": "L3", "T": "T",
             "T0": "T0", "T0-single": "T0-single", "B1-strong": "B1-strong"}
    files.update({n: f"{n}_{modes[n]}" for n in API_NAME.values()})   # amendment 13: the mode is in the file name
    present = [v for v in VARIANTS if os.path.exists(os.path.join(D.RENDER, f"{split}_{v}", "meta.jsonl"))]
    for v in present:                                                    # one mode for every level, as modes.json
        for n in API_NAME.values():
            other = "answers" if modes[n] == "probabilities" else "probabilities"
            bad = os.path.join(R, "final", split, "noise", v, f"{n}_{other}.json")
            if os.path.exists(bad):
                raise SystemExit(f"{bad} is in mode {other}, modes.json says {modes[n]}: the levels must not mix "
                                 f"scorings (ask that level again in {modes[n]})")
            p = os.path.join(R, "final", split, "noise", v, f"{n}_{modes[n]}.json")
            if os.path.exists(p) and API.sealed_split(split):
                mp = API.meta_path(p)
                mm = json.load(open(mp)) if os.path.exists(mp) else None
                if mm is None or mm["missing"] or mm["setting"] != eff[n]["setting"]:
                    raise SystemExit(f"{p}: sidecar {mm} (needs 0 missing at {eff[n]['setting']})")
    rows = {v: D.load_rows(f"{split}_{v}") for v in present}
    ctx = {v: C.Context(f"{split}_{v}") for v in present}
    res = {"split": split, "variants": present, "api_modes": modes, "api_settings": {n: eff[n]["setting"] for n in eff},
           "api_overrides": {n: eff[n]["override"] for n in eff if eff[n]["override"]},
           "detector": {}, "parts": {}, "gap_change": {}, "trust": {}, "missing": []}
    dec, T = {}, {}
    for v in present:
        dec[v], T[v] = {}, {}
        for n, f in files.items():
            p = os.path.join(R, "final", split, "noise", v, f"{f}.json")
            if not os.path.exists(p):
                res["missing"].append(f"{v} {n}")
                continue
            d = keyed(json.load(open(p)))
            dec[v][n] = d if n == "B1-strong" else S.decide(d, *th[n])
            T[v][n] = S.unit_table(rows[v], dec[v][n], sg)
        res["detector"][v] = detector(rows[v], ctx[v])
        res["trust"][v] = GR.natural_report(GR.natural_points([r for r in rows[v] if r.get("subset") is None], ctx[v]),
                                            dec[v])["trust"]                       # main body (fix check minor 2)
    if "dclean" not in present:
        raise SystemExit("the clean level is missing")
    for v in present:
        if v == "dclean":
            continue
        for part in PARTS:
            us = sorted(u for u, x in T["dclean"].get("2d", {}).items() if x["part"] == part and x["subset"] is None)

            def rt(lv, n, us=us):
                return np.array([T[lv][n][u]["right"] for u in us], float)
            sysn = [n for n in files if n in T["dclean"] and n in T[v]]
            res["parts"].setdefault(v, {})[part] = {n: {"clean": float(rt("dclean", n).mean()),
                                                       "degraded": float(rt(v, n).mean())} for n in sysn}
            for n in sysn:
                if n == "2d":
                    continue
                a = (rt(v, "2d") - rt(v, n)) - (rt("dclean", "2d") - rt("dclean", n))
                c = GR.criterion(us, cl, {}, lambda w, a=a: GR.wmean(w, a), lambda a=a: float(a.mean()))
                res["gap_change"].setdefault(v, {}).setdefault(part, {})[f"2d - {n}"] = {"point": c["point"],
                                                                                          "ci95": c["ci95"]}
        readers = [n for n in readers_g5 if all(n in T[lv] for lv in ("dclean", v))]
        if len(readers) == len(readers_g5) and "2d" in T[v]:
            us_all, is_r, val = g5_values(T, v, readers)
            c = GR.criterion(us_all, cl, {}, lambda w: 0.5 * GR.wmean(w[:, is_r], val[is_r]) +
                             0.5 * GR.wmean(w[:, ~is_r], val[~is_r]),
                             lambda: float(0.5 * val[is_r].mean() + 0.5 * val[~is_r].mean()))
            g = {"readers": readers, "point": c["point"], "ci95": c["ci95"]}
            for f in ("ci95_normal", "n_clusters", "df", "dominant_factor", "t_crit"):  # package v0.6 15.2 (review minor 2)
                if f in c:
                    g[f] = c[f]
            if v == "dnoise10":
                g["pass"] = bool(c["point"] >= st["grounding"]["g5_margin"] and c["ci95"][0] > 0)
                res["G5"] = g
            else:
                res.setdefault("described", {})[f"G5 statistic at {v}"] = g
            # package v0.6 15.7: sensitivity rows (described, no threshold)
            sens = {}
            for tag, rs in (("readers with T", list(readers) + ["T"]),
                            ("readers without the old head", [n for n in readers if n != "L1"])):
                if all(n in T[lv] for n in rs for lv in ("dclean", v)):
                    ua, ir, vv = g5_values(T, v, rs)
                    sens[tag] = {"readers": rs, **g5_stat(GR, cl, ua, ir, vv)}
            nz = np.array([TR.noise_name(T["dclean"]["2d"][u]["noise"]) for u in us_all])
            for name in sorted(set(nz)):
                sens[f"noise {name}: only"] = g5_stat(GR, cl, us_all, is_r, val, nz == name)
                sens[f"noise {name}: left out"] = g5_stat(GR, cl, us_all, is_r, val, nz != name)
            lab = {f: [T["dclean"]["2d"][u][f] for u in us_all] for f in FIVE}
            se5, info5 = boot_se_factors(us_all, lab, lambda w: 0.5 * GR.wmean(w[:, is_r], val[is_r]) +
                                         0.5 * GR.wmean(w[:, ~is_r], val[~is_r]))
            pt = float(0.5 * val[is_r].mean() + 0.5 * val[~is_r].mean())
            sens["five factors"] = {"point": pt, "ci95_t": [pt - info5["t_crit"] * se5, pt + info5["t_crit"] * se5],
                                    "ci95_normal": [pt - 1.96 * se5, pt + 1.96 * se5], "se": se5, **info5}
            res.setdefault("G5_sensitivity", {})[v] = sens
    if split != "dev" and "G5" not in res:                 # post-fix review minor 3: G5 is never silently absent
        raise SystemExit(f"G5 not computed on {split}: a reader or the main system lacks a file at dclean or dnoise10 "
                         f"({res.get('missing')}); run the missing step, no metric is written")
    json.dump(res, open(f"results/main_v04/noise_{split}.json", "w"), indent=1, default=str)
    print(json.dumps({k: res[k] for k in ("variants", "api_modes", "missing")}))
    print("G5:", json.dumps(res.get("G5")))
    for v, parts in res["parts"].items():
        for part, x in parts.items():
            print(v, part, json.dumps({n: [round(y["clean"], 3), round(y["degraded"], 3)] for n, y in x.items()}))


if __name__ == "__main__":
    cmd = sys.argv[1]
    if cmd == "render":
        render(sys.argv[2], sys.argv[3])
    elif cmd == "front":
        front(sys.argv[2], sys.argv[3])
    elif cmd == "local":
        local(sys.argv[2], sys.argv[3])
    elif cmd == "api":
        lim = int(sys.argv[sys.argv.index("--limit") + 1]) if "--limit" in sys.argv else None
        usd = float(sys.argv[sys.argv.index("--max-usd") + 1]) if "--max-usd" in sys.argv else 400.0
        api(sys.argv[2], sys.argv[3], sys.argv[4], sys.argv[5], lim, max_usd=usd)
    elif cmd == "report":
        report(sys.argv[2])
    else:
        raise SystemExit(__doc__)
